// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address from, uint256 tokenId) public {
        vm.assume(caller != address(0));
        vm.assume(from != address(0));
        bytes memory data = "";
        vm.prank(caller);
        bytes4 ret = c.onERC721Received(caller, from, tokenId, data);
        assertTrue(ret == 0x150b7a02);
    }
}
